const esc = (str) => String(str || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const fmtMoney = (n) => `${currency} ${Number(n || 0).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

const campaignRowsHtml = c.campaigns.length === 0
  ? '<tr><td colspan="7" style="text-align:center;color:#6b7280;padding:16px;">No campaign activity this period.</td></tr>'
  : c.campaigns.map(camp => `
    <tr>
      <td>${esc(camp.campaign_name)}</td>
      <td>${fmtMoney(camp.spend)}</td>
      <td>${camp.impressions.toLocaleString()}</td>
      <td>${camp.clicks.toLocaleString()}</td>
      <td>${camp.ctr}%</td>
      <td>${fmtMoney(camp.cpc)}</td>
      <td>${camp.results.toLocaleString()}</td>
    </tr>`).join('');

const creativeCardsHtml = a.ads.length === 0
  ? '<p style="color:#6b7280;font-size:13px;">No ad creative data available this period.</p>'
  : a.ads.map(ad => `
    <div class="creative-card" style="break-inside:avoid;">
      ${ad.thumbnail_url ? `<div class="creative-thumb" style="background-image:url('${esc(ad.thumbnail_url)}')"></div>` : '<div class="creative-thumb creative-thumb-placeholder">\ud83c\udfaf</div>'}
      <div class="creative-body">
        <div class="creative-meta">${esc(ad.campaign_name)}</div>
        <p class="creative-text">${esc((ad.ad_name || 'Untitled Ad').slice(0, 80))}</p>
        <div class="creative-stats">
          <span class="cstat">${fmtMoney(ad.spend)} spend</span>
          <span class="cstat">${ad.ctr}% CTR</span>
          <span class="cstat">${ad.results} results</span>
        </div>
      </div>
    </div>`).join('');

const nextStepCardsHtml = stepLines.map((step, i) => `
  <div class="step-card" style="break-inside:avoid;">
    <div class="step-num">${i + 1}</div>
    <p class="step-text">${esc(step)}</p>
  </div>`).join('');

const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Meta Ads Weekly Performance Report \u2014 ${esc(weekLabel)}</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap');
  * { margin:0; padding:0; box-sizing:border-box; }
