  .section h2 { font-size:22px; font-weight:700; margin-bottom:16px; color:#1a1a2e; }

  .header { background:linear-gradient(135deg,#1a1a2e 0%,#16213e 50%,#0f3460 100%); color:#fff; padding:40px; break-inside:avoid; }
  .header-top { display:flex; justify-content:space-between; align-items:center; margin-bottom:16px; }
  .brand { font-size:13px; font-weight:600; letter-spacing:3px; text-transform:uppercase; color:#e94560; }
  .report-badge { background:rgba(233,69,96,0.2); border:1px solid #e94560; color:#e94560; padding:4px 14px; border-radius:20px; font-size:12px; font-weight:600; }
  .header h1 { font-size:32px; font-weight:800; margin-bottom:8px; }
  .header .week { font-size:15px; color:rgba(255,255,255,0.6); }
  .header-stats { display:grid; grid-template-columns:repeat(4,1fr); gap:16px; margin-top:28px; }
  .hstat { background:rgba(255,255,255,0.07); border-radius:12px; padding:16px; text-align:center; break-inside:avoid; }
  .hstat-val { font-size:22px; font-weight:800; color:#e94560; }
  .hstat-label { font-size:11px; color:rgba(255,255,255,0.5); text-transform:uppercase; letter-spacing:1px; margin-top:4px; }

  .combined-grid { display:grid; grid-template-columns:repeat(4,1fr); gap:12px; margin-bottom:8px; }
  .combined-card { background:linear-gradient(135deg,#1a1a2e,#0f3460); border-radius:12px; padding:20px; text-align:center; break-inside:avoid; }
  .combined-val { font-size:24px; font-weight:800; color:#e94560; }
  .combined-label { font-size:11px; color:rgba(255,255,255,0.6); text-transform:uppercase; letter-spacing:1px; margin-top:6px; }
  .combined-sub { font-size:10px; color:rgba(255,255,255,0.35); margin-top:2px; }

  .stats-grid { display:grid; grid-template-columns:repeat(4,1fr); gap:12px; margin-bottom:24px; }
  .stat-card { background:#f8f9ff; border-radius:12px; padding:16px; text-align:center; border:1px solid #e8eaf6; break-inside:avoid; }
  .stat-val { font-size:22px; font-weight:800; color:#1a1a2e; }
  .stat-label { font-size:11px; color:#6b7280; text-transform:uppercase; letter-spacing:0.5px; margin-top:4px; }

  .chart-row { display:grid; grid-template-columns:1fr 1fr; gap:20px; margin:20px 0; break-inside:avoid; }
  .chart-box { background:#f8f9ff; border-radius:12px; padding:16px; border:1px solid #e8eaf6; break-inside:avoid; }
  .chart-box img { width:100%; border-radius:8px; display:block; }
  .chart-title { font-size:12px; font-weight:600; color:#6b7280; text-transform:uppercase; letter-spacing:1px; margin-bottom:10px; }

  .ai-section { background:linear-gradient(135deg,#f0f4ff,#f5f0ff); border-radius:16px; padding:28px; margin-bottom:24px; border:1px solid #e0e7ff; break-inside:avoid; }
  .ai-badge { display:inline-flex; align-items:center; gap:6px; background:#e94560; color:#fff; padding:4px 12px; border-radius:20px; font-size:11px; font-weight:700; letter-spacing:1px; text-transform:uppercase; margin-bottom:16px; }
  .ai-text { font-size:14px; line-height:1.8; color:#374151; white-space:pre-wrap; }

  .campaign-table { width:100%; border-collapse:collapse; margin-top:16px; font-size:13px; }
  .campaign-table th { background:#1a1a2e; color:#fff; text-align:left; padding:10px 12px; font-size:11px; text-transform:uppercase; letter-spacing:0.5px; }
  .campaign-table td { padding:10px 12px; border-bottom:1px solid #eef0f5; color:#374151; }
  .campaign-table tr:nth-child(even) { background:#f8f9ff; }

