  .creative-meta { font-size:10px; color:#9ca3af; margin-bottom:4px; text-transform:uppercase; letter-spacing:0.5px; }
  .creative-text { font-size:12px; line-height:1.5; color:#374151; margin-bottom:8px; min-height:32px; }
  .creative-stats { display:flex; flex-wrap:wrap; gap:6px; }
  .cstat { font-size:10px; color:#6b7280; background:#f3f4f6; padding:3px 7px; border-radius:6px; }

  .next-steps { display:grid; grid-template-columns:1fr 1fr; gap:12px; margin-top:16px; }
  .step-card { background:linear-gradient(135deg,#fff5f7,#fff); border:1px solid #fecdd3; border-radius:12px; padding:20px; break-inside:avoid; }
  .step-num { width:28px; height:28px; background:#e94560; color:#fff; border-radius:50%; display:flex; align-items:center; justify-content:center; font-size:13px; font-weight:700; margin-bottom:10px; }
  .step-text { font-size:13px; line-height:1.6; color:#374151; }

  .footer { background:#1a1a2e; color:rgba(255,255,255,0.4); text-align:center; padding:24px; font-size:12px; break-inside:avoid; }
  .footer strong { color:#e94560; }
</style>
</head>
<body>
<div class="page">

  <div class="header">
    <div class="header-top">
      <span class="brand">${esc(companyName)}</span>
      <span class="report-badge">Meta Ads Weekly Report</span>
    </div>
    <h1>Ads Performance Report</h1>
    <p class="week">Period: ${esc(weekLabel)}</p>
    <div class="header-stats">
      <div class="hstat"><div class="hstat-val">${fmtMoney(c.summary.total_spend)}</div><div class="hstat-label">Total Spend</div></div>
      <div class="hstat"><div class="hstat-val">${c.summary.total_clicks.toLocaleString()}</div><div class="hstat-label">Total Clicks</div></div>
      <div class="hstat"><div class="hstat-val">${c.summary.avg_ctr}%</div><div class="hstat-label">Average CTR</div></div>
      <div class="hstat"><div class="hstat-val">${c.summary.total_results.toLocaleString()}</div><div class="hstat-label">Total Results</div></div>
    </div>
  </div>

  <div class="section">
    <div class="section-title">Account Performance Overview</div>
    <div class="combined-grid">
      <div class="combined-card"><div class="combined-val">${fmtMoney(c.summary.avg_cpc)}</div><div class="combined-label">Avg CPC</div><div class="combined-sub">Cost per click</div></div>
      <div class="combined-card"><div class="combined-val">${fmtMoney(c.summary.avg_cpm)}</div><div class="combined-label">Avg CPM</div><div class="combined-sub">Cost per 1,000 impr.</div></div>
      <div class="combined-card"><div class="combined-val">${fmtMoney(c.summary.avg_cost_per_result)}</div><div class="combined-label">Cost / Result</div><div class="combined-sub">Blended</div></div>
      <div class="combined-card"><div class="combined-val">${c.summary.overall_roas ?? 'N/A'}</div><div class="combined-label">ROAS</div><div class="combined-sub">Revenue / spend</div></div>
    </div>
  </div>

  <div class="section">
    <div class="section-title">AI-Powered Analysis</div>
    <div class="ai-section">
      <span class="ai-badge">\ud83e\udd16 Executive Summary</span>
      <p class="ai-text">${esc(execSummary)}</p>
    </div>
  </div>

  <div class="section">
    <div class="section-title">Campaign Performance</div>
    <div class="stats-grid">
      <div class="stat-card"><div class="stat-val">${c.summary.campaign_count}</div><div class="stat-label">Active Campaigns</div></div>
      <div class="stat-card"><div class="stat-val">${c.summary.total_impressions.toLocaleString()}</div><div class="stat-label">Impressions</div></div>
      <div class="stat-card"><div class="stat-val">${c.summary.total_reach.toLocaleString()}</div><div class="stat-label">Reach</div></div>
      <div class="stat-card"><div class="stat-val">${fmtMoney(c.summary.total_revenue)}</div><div class="stat-label">Revenue Tracked</div></div>
    </div>
    <div class="chart-row">
      <div class="chart-box"><div class="chart-title">Daily Ad Spend</div><img src="${charts.spendChartUrl}" alt="Daily Spend"/></div>
      <div class="chart-box"><div class="chart-title">Impressions vs Clicks</div><img src="${charts.clicksImpressionsChartUrl}" alt="Impressions vs Clicks"/></div>
    </div>
    <div class="chart-row">
      <div class="chart-box"><div class="chart-title">Top Campaigns by Spend</div><img src="${charts.campaignSpendChartUrl}" alt="Top Campaigns"/></div>
      <div class="chart-box"><div class="chart-title">Daily CTR Trend</div><img src="${charts.ctrChartUrl}" alt="CTR Trend"/></div>
    </div>
    <div class="ai-section">
      <span class="ai-badge">\ud83d\udcca Campaign Insights</span>
      <p class="ai-text">${esc(campAnalysis)}</p>
    </div>
    <div class="section-title" style="margin-top:8px;">Campaign Breakdown</div>
    <table class="campaign-table">
      <thead><tr><th>Campaign</th><th>Spend</th><th>Impressions</th><th>Clicks</th><th>CTR</th><th>CPC</th><th>Results</th></tr></thead>
      <tbody>${campaignRowsHtml}</tbody>
    </table>
  </div>

  <div class="section">
    <div class="section-title">Creative Performance</div>
    <div class="ai-section">
      <span class="ai-badge">\ud83c\udfa8 Creative Insights</span>
      <p class="ai-text">${esc(creativeAnalysis)}</p>
    </div>
    <div class="section-title" style="margin-top:8px;">Top Performing Ads This Period</div>
    <div class="creative-grid">${creativeCardsHtml}</div>
  </div>

  <div class="section">
    <div class="section-title">Budget &amp; Efficiency</div>
    <div class="ai-section">
      <span class="ai-badge">\ud83d\udcb0 Budget Insights</span>
      <p class="ai-text">${esc(budgetInsights)}</p>
    </div>
  </div>

  <div class="section">
    <div class="section-title">Action Plan</div>
    <h2>Next Steps</h2>
    <div class="next-steps">${nextStepCardsHtml}</div>
  </div>

  <div class="footer">
    Generated automatically by <strong>Meta Ads Weekly Performance Workflow</strong> &bull; ${esc(weekLabel)}
  </div>

</div>
</body>
</html>`;

return [{ json: { html, weekLabel } }];

